/**
 * Qiskit Python Subset Parser & Code Generator
 * Enables bi-directional synchronization between visual circuit canvas and code.
 */

import { Circuit, Gate, GateType } from '../types/quantum';

export interface CodeParseResult {
  success: boolean;
  circuit?: Circuit;
  errors: { line: number; message: string }[];
}

export class CodeConverter {
  /**
   * Generates readable Qiskit Python code from a Circuit object
   */
  static circuitToQiskit(circuit: Circuit): string {
    const lines: string[] = [
      '# Quantum Algorithm Implementation',
      '# Generated by AI Quantum Tutor Platform',
      'from qiskit import QuantumCircuit',
      'import numpy as np',
      '',
      `# Initialize ${circuit.numQubits}-qubit quantum circuit`,
      `qc = QuantumCircuit(${circuit.numQubits})`,
      '',
    ];

    const sortedGates = [...circuit.gates].sort((a, b) => a.col - b.col);

    let hasMeasurements = false;

    for (const g of sortedGates) {
      switch (g.type) {
        case 'I':
          lines.push(`qc.id(${g.qubit})`);
          break;
        case 'H':
          lines.push(`qc.h(${g.qubit})`);
          break;
        case 'X':
          lines.push(`qc.x(${g.qubit})`);
          break;
        case 'Y':
          lines.push(`qc.y(${g.qubit})`);
          break;
        case 'Z':
          lines.push(`qc.z(${g.qubit})`);
          break;
        case 'S':
          lines.push(`qc.s(${g.qubit})`);
          break;
        case 'T':
          lines.push(`qc.t(${g.qubit})`);
          break;
        case 'Sdg':
          lines.push(`qc.sdg(${g.qubit})`);
          break;
        case 'Tdg':
          lines.push(`qc.tdg(${g.qubit})`);
          break;
        case 'RX':
          lines.push(`qc.rx(${g.params?.theta?.toFixed(4) || 'np.pi'}, ${g.qubit})`);
          break;
        case 'RY':
          lines.push(`qc.ry(${g.params?.theta?.toFixed(4) || 'np.pi'}, ${g.qubit})`);
          break;
        case 'RZ':
          lines.push(`qc.rz(${g.params?.theta?.toFixed(4) || 'np.pi'}, ${g.qubit})`);
          break;
        case 'CX':
          lines.push(`qc.cx(${g.qubit}, ${g.targetQubit ?? (g.qubit === 0 ? 1 : 0)})`);
          break;
        case 'CZ':
          lines.push(`qc.cz(${g.qubit}, ${g.targetQubit ?? (g.qubit === 0 ? 1 : 0)})`);
          break;
        case 'SWAP':
          lines.push(`qc.swap(${g.qubit}, ${g.targetQubit ?? (g.qubit === 0 ? 1 : 0)})`);
          break;
        case 'BARRIER':
          lines.push('qc.barrier()');
          break;
        case 'MEASURE':
          hasMeasurements = true;
          lines.push(`qc.measure(${g.qubit}, ${g.qubit})`);
          break;
      }
    }

    if (!hasMeasurements) {
      lines.push('');
      lines.push('# Measure all qubits into classical registers');
      lines.push('qc.measure_all()');
    }

    return lines.join('\n');
  }

  /**
   * Parses supported Qiskit Python subset into a Circuit object
   */
  static parseQiskit(code: string): CodeParseResult {
    const lines = code.split('\n');
    const errors: { line: number; message: string }[] = [];
    let numQubits = 2;
    const gates: Gate[] = [];
    let gateIdCounter = 1;
    const qubitCols: number[] = [0, 0, 0, 0, 0, 0, 0, 0];

    for (let i = 0; i < lines.length; i++) {
      const lineNum = i + 1;
      const rawLine = lines[i].trim();

      // Skip blank lines and comments
      if (!rawLine || rawLine.startsWith('#')) continue;

      // Skip imports
      if (rawLine.startsWith('import ') || rawLine.startsWith('from ')) continue;

      // Match QuantumCircuit(N)
      const qcMatch = rawLine.match(/QuantumCircuit\s*\(\s*(\d+)/);
      if (qcMatch) {
        const qCount = parseInt(qcMatch[1], 10);
        if (qCount < 1 || qCount > 8) {
          errors.push({
            line: lineNum,
            message: `Unsupported qubit count ${qCount}. Browser simulator supports 1 to 8 qubits.`,
          });
        } else {
          numQubits = qCount;
        }
        continue;
      }

      // Match measure_all()
      if (rawLine.includes('measure_all()')) {
        for (let q = 0; q < numQubits; q++) {
          const col = qubitCols[q] || 0;
          gates.push({
            id: `gate_${gateIdCounter++}`,
            type: 'MEASURE',
            qubit: q,
            col,
          });
          qubitCols[q] = col + 1;
        }
        continue;
      }

      // Match barrier
      if (rawLine.includes('barrier()')) {
        const maxCol = Math.max(...qubitCols.slice(0, numQubits), 0);
        for (let q = 0; q < numQubits; q++) {
          gates.push({
            id: `gate_${gateIdCounter++}`,
            type: 'BARRIER',
            qubit: q,
            col: maxCol,
          });
          qubitCols[q] = maxCol + 1;
        }
        continue;
      }

      // Match 1-qubit gates: qc.h(0), qc.x(1), etc.
      const singleGateMatch = rawLine.match(/qc\.(h|x|y|z|s|t|sdg|tdg|id)\s*\(\s*(\d+)\s*\)/i);
      if (singleGateMatch) {
        const gName = singleGateMatch[1].toLowerCase();
        const q = parseInt(singleGateMatch[2], 10);

        if (q >= numQubits) {
          errors.push({
            line: lineNum,
            message: `Qubit index ${q} is out of bounds for circuit with ${numQubits} qubits.`,
          });
          continue;
        }

        const typeMap: Record<string, GateType> = {
          h: 'H',
          x: 'X',
          y: 'Y',
          z: 'Z',
          s: 'S',
          t: 'T',
          sdg: 'Sdg',
          tdg: 'Tdg',
          id: 'I',
        };

        const col = qubitCols[q] || 0;
        gates.push({
          id: `gate_${gateIdCounter++}`,
          type: typeMap[gName] || 'I',
          qubit: q,
          col,
        });
        qubitCols[q] = col + 1;
        continue;
      }

      // Match 2-qubit gates: qc.cx(0, 1), qc.cz(0, 1), qc.swap(0, 1)
      const twoGateMatch = rawLine.match(/qc\.(cx|cnot|cz|swap)\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)/i);
      if (twoGateMatch) {
        const gName = twoGateMatch[1].toLowerCase();
        const c = parseInt(twoGateMatch[2], 10);
        const t = parseInt(twoGateMatch[3], 10);

        if (c >= numQubits || t >= numQubits) {
          errors.push({
            line: lineNum,
            message: `Qubit index (${c}, ${t}) out of bounds for ${numQubits} qubits.`,
          });
          continue;
        }

        if (c === t) {
          errors.push({
            line: lineNum,
            message: `Control and target qubit cannot be the same (q${c}).`,
          });
          continue;
        }

        const type = gName === 'cz' ? 'CZ' : gName === 'swap' ? 'SWAP' : 'CX';
        const col = Math.max(qubitCols[c] || 0, qubitCols[t] || 0);

        gates.push({
          id: `gate_${gateIdCounter++}`,
          type,
          qubit: c,
          targetQubit: t,
          col,
        });

        qubitCols[c] = col + 1;
        qubitCols[t] = col + 1;
        continue;
      }

      // Match rotation gates: qc.rx(angle, q)
      const rotMatch = rawLine.match(/qc\.(rx|ry|rz)\s*\(\s*([^,]+)\s*,\s*(\d+)\s*\)/i);
      if (rotMatch) {
        const gName = rotMatch[1].toUpperCase() as GateType;
        const angleStr = rotMatch[2].trim();
        const q = parseInt(rotMatch[3], 10);

        let angle = Math.PI;
        try {
          if (angleStr.includes('np.pi')) {
            const factor = angleStr.replace('np.pi', '').replace('*', '').trim();
            if (factor === '') angle = Math.PI;
            else if (factor.startsWith('/')) angle = Math.PI / parseFloat(factor.slice(1));
            else angle = parseFloat(factor) * Math.PI;
          } else {
            angle = parseFloat(angleStr);
          }
        } catch {
          angle = Math.PI;
        }

        const col = qubitCols[q] || 0;
        gates.push({
          id: `gate_${gateIdCounter++}`,
          type: gName,
          qubit: q,
          params: { theta: angle },
          col,
        });
        qubitCols[q] = col + 1;
        continue;
      }

      // Match measurement: qc.measure(q, c)
      const measMatch = rawLine.match(/qc\.measure\s*\(\s*(\d+)\s*,\s*(\d+)\s*\)/i);
      if (measMatch) {
        const q = parseInt(measMatch[1], 10);
        const col = qubitCols[q] || 0;
        gates.push({
          id: `gate_${gateIdCounter++}`,
          type: 'MEASURE',
          qubit: q,
          col,
        });
        qubitCols[q] = col + 1;
        continue;
      }

      // If line is unknown and contains qc.
      if (rawLine.startsWith('qc.')) {
        errors.push({
          line: lineNum,
          message: `Unrecognized or unsupported instruction: "${rawLine}". Supported subset: h, x, y, z, s, t, rx, ry, rz, cx, cz, swap, barrier, measure.`,
        });
      }
    }

    if (errors.length > 0) {
      return { success: false, errors };
    }

    const circuit: Circuit = {
      id: `imported_${Date.now()}`,
      name: 'Python Qiskit Program',
      numQubits,
      gates,
      description: 'Imported from Qiskit code editor',
    };

    return {
      success: true,
      circuit,
      errors: [],
    };
  }
}
